const HWM = 16, TOTAL = 300, PROD = 3, CONS = 1;
function run(honor) {
  let buffer = 0, produced = 0, maxOcc = 0, paused = false;
  while (produced < TOTAL || buffer > 0) {
    // consumer drains CONS per tick
    buffer = Math.max(0, buffer - CONS);
    // resume once buffer fell below the mark
    if (honor && paused && buffer < HWM) paused = false;
    // producer writes PROD per tick unless backpressure paused it
    if (produced < TOTAL && !(honor && paused)) {
      const n = Math.min(PROD, TOTAL - produced);
      buffer += n;
      produced += n;
      // write() returned false: buffer crossed the high-water mark
      if (honor && buffer >= HWM) paused = true;
    }
    if (buffer > maxOcc) maxOcc = buffer;
  }
  return maxOcc;
}
const ignored = run(false);
const honored = run(true);
console.log('ignored maxBuffer=' + ignored);
console.log('honored maxBuffer=' + honored);
console.log('cap=' + HWM);
console.log(honored <= HWM + PROD && ignored > 100 ? 'BACKPRESSURE CAPS MEMORY' : 'FAIL');

